  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 8, 'g8_st3', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Vận dụng kiến thức quần thể, quần xã và hệ sinh thái để khảo sát môi trường gần trường.', '{"textWithBlanks":"Sau khảo sát, cần sắp xếp dữ liệu và rút ra [blank].","bankWords":["kết luận","mùi hương","số đo tùy ý"],"hint":"Thử từng từ trong kho vào câu “Sau khảo sát, cần sắp xếp dữ liệu và rút ra [blank].” để tạo phát biểu đúng. Từ cần chọn bắt đầu bằng “k” và gồm 2 tiếng."}'::jsonb, '{"value":"kết luận","explanation":"Từ đúng là “kết luận”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 8 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 41–47. Sinh vật và môi trường"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
$station_release$;
